 50| // ---------------------------------------------------------------------------
 51| // JSON-RPC 2.0 over stdio (JSONL) — Python bridge client
 52| // ---------------------------------------------------------------------------
 53| 
 54| interface JsonRpcRequest {
 55|   jsonrpc: "2.0";
 56|   id: number | string;
 57|   method: string;
 58|   params?: unknown;
 59| }
 60| 
 61| interface JsonRpcResponse {
 62|   jsonrpc: "2.0";
 63|   id?: number | string | null;
 64|   result?: unknown;
 65|   error?: { code: number; message: string; data?: unknown };
 66|   method?: string;
 67|   params?: unknown;
 68| }
 69| 
 70| /**
 71|  * Spawns `python3 <script> [...args]` and speaks JSON-RPC 2.0 / JSONL.
 72|  * Compatible with MCP-style servers (initialize, tools/list, tools/call)
 73|  * and any generic `method`/`params` server.
 74|  */
 75| export class JsonRpcStdioClient implements BridgeToolProvider {
 76|   private child: ChildProcessWithoutNullStreams | null = null;
 77|   private nextId = 1;
 78|   private pending = new Map<
 79|     number | string,
 80|     { resolve: (v: unknown) => void; reject: (e: Error) => void; timer: NodeJS.Timeout }
 81|   >();
 82|   private buffer = "";
 83|   private closed = false;
 84| 
 85|   constructor(
 86|     readonly scriptPath: string,
 87|     readonly scriptArgs: string[] = [],
 88|     readonly pythonBin = process.env.MUSE_BRIDGE_PYTHON ?? "python3",
 89|   ) {}
 90| 
 91|   get running(): boolean {
 92|     return this.child !== null && !this.closed;
 93|   }
 94| 
 95|   start(): void {
 96|     if (this.child) return;
 97|     const abs = path.isAbsolute(this.scriptPath)
 98|       ? this.scriptPath
 99|       : path.resolve(process.cwd(), this.scriptPath);
100|     if (!fs.existsSync(abs)) {
101|       throw new Error(`bridge script not found: ${this.scriptPath}`);
102|     }
103|     this.child = spawn(this.pythonBin, [abs, ...this.scriptArgs], {
104|       stdio: ["pipe", "pipe", "pipe"],
105|       cwd: process.cwd(),
106|     });
107|     this.closed = false;
108|     this.child.stdout.setEncoding("utf-8");
109|     this.child.stdout.on("data", (chunk) => this.onData(String(chunk)));
110|     this.child.stderr.setEncoding("utf-8");
111|     this.child.stderr.on("data", () => {
112|       /* Python logs stay on stderr; ignore here (callers may tap) */
113|     });
114|     this.child.on("close", (code) => {
115|       this.closed = true;
116|       for (const [, p] of this.pending) {
117|         clearTimeout(p.timer);
118|         p.reject(new Error(`bridge exited (code ${code})`));
119|       }
120|       this.pending.clear();
121|     });
122|     this.child.on("error", (err) => {
123|       for (const [, p] of this.pending) {
124|         clearTimeout(p.timer);
125|         p.reject(err);
126|       }
127|       this.pending.clear();
128|     });
129|   }
130| 
131|   private onData(chunk: string): void {
132|     this.buffer += chunk;
133|     let nl: number;
134|     while ((nl = this.buffer.indexOf("\n")) !== -1) {
135|       const line = this.buffer.slice(0, nl).trim();
136|       this.buffer = this.buffer.slice(nl + 1);
137|       if (!line) continue;
138|       let msg: JsonRpcResponse;
139|       try {
140|         msg = JSON.parse(line) as JsonRpcResponse;
141|       } catch {
142|         continue;
143|       }
144|       // Response to a pending request.
145|       if (msg.id !== undefined && msg.id !== null && (msg.result !== undefined || msg.error)) {
146|         const p = this.pending.get(msg.id);
147|         if (!p) continue;
148|         this.pending.delete(msg.id);
149|         clearTimeout(p.timer);
150|         if (msg.error) {
151|           p.reject(new Error(`bridge error ${msg.error.code}: ${msg.error.message}`));
152|         } else {
153|           p.resolve(msg.result);
154|         }
155|         continue;
156|       }
157|       // Server notification / request — no-op (MCP servers rarely call back).
158|     }
159|   }
160| 
161|   request(method: string, params?: unknown, timeoutMs = 30_000): Promise<unknown> {
162|     if (!this.child || this.closed) {
163|       throw new Error("bridge is not running");
164|     }
165|     const id = this.nextId++;
166|     const req: JsonRpcRequest = { jsonrpc: "2.0", id, method, ...(params !== undefined ? { params } : {}) };
167|     return new Promise((resolve, reject) => {
168|       const timer = setTimeout(() => {
169|         this.pending.delete(id);
170|         reject(new Error(`bridge request timed out: ${method}`));
171|       }, timeoutMs);
172|       this.pending.set(id, { resolve, reject, timer });
173|       try {
174|         this.child!.stdin.write(JSON.stringify(req) + "\n");
175|       } catch (err) {
176|         this.pending.delete(id);
177|         clearTimeout(timer);
178|         reject(err as Error);
179|       }
180|     });
181|   }
182| 
183|   notify(method: string, params?: unknown): void {
184|     if (!this.child || this.closed) return;
185|     this.child.stdin.write(
186|       JSON.stringify({ jsonrpc: "2.0", method, ...(params !== undefined ? { params } : {}) }) + "\n",
187|     );
188|   }
189| 
190|   async initialize(): Promise<unknown> {
191|     const result = await this.request("initialize", {
192|       protocolVersion: "2024-11-05",
193|       capabilities: {},
194|       clientInfo: { name: "muse-ts", version: "1.0.0" },
195|     });
196|     this.notify("notifications/initialized");
197|     return result;
198|   }
199| 
200|   async listTools(): Promise<{ name: string; description?: string; inputSchema?: unknown }[]> {

200|   async listTools(): Promise<{ name: string; description?: string; inputSchema?: unknown }[]> {
201|     const result = (await this.request("tools/list", {})) as {
202|       tools?: { name: string; description?: string; inputSchema?: unknown }[];
203|     };
204|     return Array.isArray(result.tools) ? result.tools : [];
205|   }
206| 
207|   async callTool(name: string, args: Record<string, unknown>): Promise<string> {
208|     const result = (await this.request("tools/call", { name, arguments: args })) as {
209|       content?: { type?: string; text?: string }[];
210|     };
211|     if (Array.isArray(result.content)) {
212|       return result.content.map((c) => c.text ?? JSON.stringify(c)).join("\n");
213|     }
214|     return JSON.stringify(result).slice(0, 20_000);
215|   }
216| 
217|   async close(): Promise<void> {
218|     if (!this.child) return;
219|     try {
220|       this.child.stdin.end();
221|     } catch {
222|       /* ignore */
223|     }
224|     const child = this.child;
225|     await new Promise<void>((resolve) => {
226|       const timer = setTimeout(() => {
227|         try {
228|           child.kill("SIGKILL");
229|         } catch {
230|           /* ignore */
231|         }
232|         resolve();
233|       }, 3000);
234|       child.on("close", () => {
235|         clearTimeout(timer);
236|         resolve();
237|       });
238|     });
239|     this.child = null;
240|     this.closed = true;
241|   }
242| }
