244| // ---------------------------------------------------------------------------
245| // MSP-compatible stdio host (minimal subset, JSONL)
246| // ---------------------------------------------------------------------------
247| 
248| interface MspSession {
249|   id: string;
250|   workspace: string;
251|   model: string;
252|   reasoningEffort: ReasoningEffort;
253|   messages: ChatMessage[];
254|   createdAt: string;
255| }
256| 
257| async function runServe(opts: {
258|   noSessionLog?: boolean;
259|   disableWrite?: boolean;
260|   disableShell?: boolean;
261|   trustWorkspace?: boolean;
262| }): Promise<void> {
263|   void opts;
264|   const sessions = new Map<string, MspSession>();
265|   let buffer = "";
266|   process.stdin.setEncoding("utf-8");
267| 
268|   const send = (id: number | string | null, result?: unknown, error?: { code: number; message: string }) => {
269|     const msg: Record<string, unknown> = { jsonrpc: "2.0", id };
270|     if (error) msg.error = error;
271|     else msg.result = result ?? null;
272|     process.stdout.write(JSON.stringify(msg) + "\n");
273|   };
274| 
275|   const handle = async (raw: JsonRpcRequest & { id: number | string }): Promise<void> => {
276|     const { id, method, params } = raw;
277|     const p = (params ?? {}) as Record<string, unknown>;
278|     try {
279|       switch (method) {
280|         case "initialize": {
281|           send(id, {
282|             protocolVersion: "msp/1",
283|             serverInfo: { name: "muse-ts", version: "1.0.0", rustFree: true },
284|             capabilities: { streaming: false, tools: true },
285|           });
286|           break;
287|         }
288|         case "model/list": {
289|           const resolved = resolveCredential();
290|           if (!resolved) {
291|             send(id, undefined, { code: -32001, message: "not logged in" });
292|             break;
293|           }
294|           const client = new MetaChatClient({
295|             token: resolved.token,
296|             baseUrl: String(p.baseUrl ?? resolved.baseUrl),
297|             model: "muse-spark-1.3",
298|           });
299|           try {
300|             const models = await client.listModels();
301|             send(id, { models });
302|           } catch (err) {
303|             send(id, undefined, { code: -32002, message: (err as Error).message });
304|           }
305|           break;
306|         }
307|         case "session/start": {
308|           const workspace = path.resolve(String(p.workspace ?? process.cwd()));
309|           const s: MspSession = {
310|             id: randomUUID(),
311|             workspace,
312|             model: String(p.model ?? "muse-spark-1.3"),
313|             reasoningEffort: (String(p.reasoningEffort ?? "high") as ReasoningEffort) ?? "high",
314|             messages: [
315|               { role: "system", content: String(p.systemPrompt ?? "You are muse-ts, a terminal coding assistant.") },
316|             ],
317|             createdAt: new Date().toISOString(),
318|           };
319|           sessions.set(s.id, s);
320|           send(id, { sessionId: s.id, workspace: s.workspace, model: s.model });
321|           break;
322|         }
323|         case "session/list": {
324|           send(id, {
325|             sessions: [...sessions.values()].map((s) => ({
326|               id: s.id,
327|               workspace: s.workspace,
328|               model: s.model,
329|               messageCount: s.messages.length,
330|             })),
331|           });
332|           break;
333|         }
334|         case "turn/start": {
335|           const s = sessions.get(String(p.sessionId ?? ""));
336|           if (!s) {
337|             send(id, undefined, { code: -32003, message: "unknown session" });
338|             break;
339|           }
340|           const prompt = String(p.prompt ?? "");
341|           if (!prompt) {
342|             send(id, undefined, { code: -32602, message: "prompt is required" });
343|             break;
344|           }
345|           const resolved = resolveCredential();
346|           if (!resolved) {
347|             send(id, undefined, { code: -32001, message: "not logged in" });
348|             break;
349|           }
350|           s.messages.push({ role: "user", content: prompt });
351|           const client = new MetaChatClient({
352|             token: resolved.token,
353|             baseUrl: resolved.baseUrl,
354|             model: s.model,
355|             reasoningEffort: s.reasoningEffort,
356|           });
357|           const reply = await client.chatOnce(s.messages, []);
358|           s.messages.push(reply);
359|           send(id, { text: reply.content, model: s.model });
360|           break;
361|         }
362|         case "usage/read": {
363|           send(id, { sessions: sessions.size, note: "usage accounting is client-side in muse-ts" });
364|           break;
365|         }
366|         default: {
367|           send(id, undefined, { code: -32601, message: `method not found: ${method}` });
368|         }
369|       }
370|     } catch (err) {
371|       send(id, undefined, { code: -32603, message: (err as Error).message });
372|     }
373|   };
374| 
375|   process.stdin.on("data", (chunk) => {
376|     buffer += String(chunk);
377|     let nl: number;
378|     // Support both JSONL and LSP Content-Length framing.
379|     while (true) {
380|       if (buffer.startsWith("Content-Length:")) {
381|         const sep = buffer.indexOf("\r\n\r\n");
382|         if (sep === -1) return;
383|         const header = buffer.slice(0, sep);
384|         const m = /Content-Length:\s*(\d+)/i.exec(header);
385|         const len = m ? Number(m[1]) : -1;
386|         if (len < 0 || buffer.length < sep + 4 + len) return;
387|         const body = buffer.slice(sep + 4, sep + 4 + len);
388|         buffer = buffer.slice(sep + 4 + len);
389|         try {
390|           const msg = JSON.parse(body) as JsonRpcRequest & { id: number | string };
391|           if (msg.method && msg.id !== undefined) void handle(msg);
392|         } catch {
393|           /* ignore malformed frame */
394|         }
395|         continue;
396|       }
397|       nl = buffer.indexOf("\n");
398|       if (nl === -1) return;
399|       const line = buffer.slice(0, nl).trim();
400|       buffer = buffer.slice(nl + 1);
401|       if (!line) continue;
402|       try {
403|         const msg = JSON.parse(line) as JsonRpcRequest & { id: number | string };
404|         if (msg.method && msg.id !== undefined) void handle(msg);
405|       } catch {
406|         /* ignore malformed line */
407|       }
408|     }
409|   });
410| 
411|   await new Promise<void>((resolve) => {
412|     process.stdin.on("close", () => resolve());
413|     process.stdin.on("end", () => resolve());
414|   });
415| }
