421| function checkBin(name: string): string | null {
422|   const prefix = process.env.PREFIX ?? "/data/data/com.termux/files/usr";
423|   const candidates = [
424|     path.join(prefix, "bin", name),
425|     `/usr/bin/${name}`,
426|     name,
427|   ];
428|   for (const c of candidates) {
429|     try {
430|       const r = spawnSync(c, ["--version"], { stdio: "ignore" });
431|       if (r.status === 0 || r.error === undefined) return c;
432|     } catch {
433|       continue;
434|     }
435|     // Fallback: `command -v`.
436|     try {
437|       const r = spawnSync("sh", ["-c", `command -v ${name}`], { encoding: "utf-8" });
438|       if (r.status === 0 && r.stdout.trim().length > 0) return r.stdout.trim();
439|     } catch {
440|       continue;
441|     }
442|   }
443|   return null;
444| }
