541|   const program = new Command();
542|   program
543|     .name("muse-ts")
544|     .description("muse-ts — interactive terminal coding agent (native TypeScript, no Rust)")
545|     .version("1.0.0")
546|     .option("--provider <mode>", "startup provider: echo, meta, or local", "meta")
547|     .option("--model <model>", "model id for non-echo providers")
548|     .option("--reasoning-effort <effort>", "meta reasoning effort", "high")
549|     .option("--base-url <url>", "override the Meta provider base URL")
550|     .option("--workspace <path>", "workspace root for tools (default: CWD)")
551|     .option("--approval-mode <mode>", "tool approval mode: untrusted|on-request|never", "on-request")
552|     .option("--parallel-tool-calls", "enable Meta API parallel tool calls")
553|     .option("--no-parallel-tool-calls", "disable Meta API parallel tool calls")
554|     .option("--bridge-script <path>", "Python JSON-RPC JSONL server to attach as tools")
555|     .option("--session-id <uuid>", "use a specific session id")
556|     .option("--no-session-log", "do not persist session logs to disk")
557|     .option("--yolo", "disable approval (alias for --approval-mode never)")
558|     .option("--disable-approval", "disable approval prompts")
559|     .option("--trust-workspace", "trust workspace (accepted for Rust-CLI compat)")
560|     .option("--disable-sandbox", "accepted for Rust-CLI compat (no sandbox in TS preview)")
561|     .argument("[prompt]", "initial prompt; starts the interactive TUI with this message queued");
562| 
563|   program
564|     .command("login")
565|     .description("Log in with your Meta account: approve a code in your browser (native TS device flow)")
566|     .option("--auth-base-url <url>", "override OAuth base URL")
567|     .option("--api-base-url <url>", "override Model API base URL")
568|     .option("--no-open-browser", "do not auto-open the verification URL")
569|     .action(async (cmdOpts: { authBaseUrl?: string; apiBaseUrl?: string; openBrowser?: boolean }) => {
